const fixtureDir = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../integrations/fixtures/observatory",
);

function load(name: string): unknown {
  return JSON.parse(readFileSync(join(fixtureDir, name), "utf8"));
}

const readingsPage = load("readings-page.json");
const readingsPage2 = load("readings-page-2.json");
const readingsEmpty = load("readings-empty.json");

type RawSensor = {
  Sensor_Name: string;
  Location_WKT: string;
  Sensor_Centroid_Longitude: number;
  Ground_Height_Above_Sea_Level: number;
  Sensor_Centroid_Latitude: number;
  Sensor_Height_Above_Ground: number | null;
  Broker_Name: string;
  Raw_ID: string;
};

type RawReading = {
  Sensor_Name: string;
  Variable: string;
  Value: number;
  Timestamp: string;
  Flagged: boolean;
};

function recordedNoiseSensor(): RawSensor {
  const page = readingsPage as { Sensors: Record<string, RawSensor> };
  const sensor = page.Sensors.PER_AIRMON_MESH1822245;
  if (!sensor) throw new Error("fixture is missing PER_AIRMON_MESH1822245");
  return sensor;
}

function sensorFromFixture(
  overrides: Partial<RawSensor> & Pick<RawSensor, "Sensor_Name" | "Raw_ID">,
): RawSensor {
  const sensor = { ...structuredClone(recordedNoiseSensor()), ...overrides };
  sensor.Location_WKT = `POINT(${sensor.Sensor_Centroid_Longitude} ${sensor.Sensor_Centroid_Latitude})`;
  return sensor;
}
import type { Db, IndexSpecification } from "mongodb";

/** Collections and their indexes (docs/ARCHITECTURE.md, "MongoDB Atlas"). */
export const INDEXES: Record<string, IndexSpecification[]> = {
  users: [],
  nights: [{ userId: 1, startedAt: -1 }],
  sensors: [{ location: "2dsphere" }],
  hotels: [{ location: "2dsphere" }],
  venues: [{ location: "2dsphere" }],
  works: [{ geometry: "2dsphere" }],
};

/** Creates every collection, then its indexes. Safe to run on every boot. */
export async function ensureIndexes(db: Db): Promise<void> {
  const existing = new Set(
    (await db.listCollections({}, { nameOnly: true }).toArray()).map((c) => c.name),
  );
  for (const [collection, specs] of Object.entries(INDEXES)) {
    if (!existing.has(collection)) await db.createCollection(collection);
    for (const spec of specs) await db.collection(collection).createIndex(spec);
  }
}

if (import.meta.main) {
  const { closeMongo, connectMongo, mongo } = await import("./mongo");
  await connectMongo();
  await ensureIndexes(mongo());
  console.log(`indexes ensured on ${Object.keys(INDEXES).length} collections`);
  await closeMongo();
}
