import { isInNightWindow, MIN_NIGHTS_FOR_ESTIMATE, nightOf, toLocalTime } from "@kip/shared/domain";
import type { AnyBulkWriteOperation, Collection } from "mongodb";
import type { Sql } from "postgres";
import { mongo } from "../../db/mongo";
import { tiger } from "../../db/tiger";

/** Architecture key columns: noise_db (Sound), no2, pm25. */
export const SENSOR_METRICS = ["noise_db", "no2", "pm25"] as const;
export type SensorMetric = (typeof SENSOR_METRICS)[number];

/** Mongo collection from docs/ARCHITECTURE.md. The 2dsphere index is on `location`. */
export const SENSORS_COLLECTION = "sensors";

export type SensorReadingInsert = {
  time: Date;
  sensorId: string;
  metric: SensorMetric;
  value: number;
};

export type SensorUpsert = {
  sensorId: string;
  name: string;
  longitude: number;
  latitude: number;
  broker: string;
  heightAboveGround: number | null;
  metrics: SensorMetric[];
  updatedAt: Date;
};

/** Observatory sensor kept for the map. `_id` is the Observatory raw id. */
export type SensorDocument = {
  _id: string;
  name: string;
  location: { type: "Point"; coordinates: [number, number] };
  broker: string;
  heightAboveGround: number | null;
  metrics: SensorMetric[];
  updatedAt: Date;
  /** Energy average of nightly Lnight. Null when fewer than 30 nights are in the window. */
  lnight30?: number | null;
  /** Indicative % highly sleep disturbed. Null when there is not enough data. */
  pctHighlySleepDisturbed?: number | null;
  /** Nights of noise inside the last 30 completed nights. */
  nights?: number;
  /** Lnight fell outside 40 to 65 dB and the curve clamped it. */
  outOfRange?: boolean;
  /** Fewer than 30 nights: the map shows the sensor and does not shade it. */
  notEnoughData?: boolean;
| `vitals` | hypertable | `time, night_id, metric (hr, hrv, resp), value` | `night` |

The 30-night Lnight per sensor is a query over `sensor_lnight_daily`. Backfill at least 30 nights
of Observatory history in hour one.

### MongoDB Atlas
| Collection | Holds | Indexes | Feature |
|---|---|---|---|
| `users` | Consent, profile choice | | `account` |
| `nights` | One summary per night: events, labels, attribution counts, hours flags, log hash, memo signature | `userId, startedAt` | `night` (others add fields through its service) |
| `sensors` | Observatory sensor, GeoJSON point, latest 30-night Lnight and %HSD | `2dsphere` | `city` |
| `hotels` | OSM hotel, GeoJSON point, placeholder booking link, `simulated` flags | `2dsphere` | `stays` |
| `venues` | OSM nightlife and sights | `2dsphere` | `stays` |
| `works` | Street Manager permits, geometry, proposed/actual times, night flag | `2dsphere` | `works` |

Hotel ranking is one pipeline: `$geoNear` on `hotels` first (only one is allowed, and it must be
the first stage), then `$lookup` with `$geoWithin` and `$centerSphere` into `sensors`, `works` and
`venues`, then the profile weights from `packages/shared/src/domain/`.

